  const png=contain && /png|webp|svg/.test(file.type); if(!png){ x.fillStyle='#fff'; x.fillRect(0,0,w,h); }
  x.drawImage(im,0,0,w,h); return {data:c.toDataURL(png?'image/png':'image/jpeg',.86),w,h,fmt:png?'PNG':'JPEG'};
